// Update pheromone weights with reinforcement + decay
const items = $input.all();
const alpha = 0.1; // Reinforcement rate
const decay = 0.05; // Decay rate (5% per hour)

const updates = [];

for (const item of items) {
  const data = item.json;

  // Reinforcement: $100 nutrient -> +alpha
  const reinforcement = alpha * (data.nutrient_usd / 100.0);

  // New weight = (old_weight * (1 - decay)) + reinforcement
  // We'll load old weight from DB and compute new weight

  updates.push({
    tendril_key: data.tendril_key,
    nutrient_usd: data.nutrient_usd,
    event_count: data.event_count,
    reinforcement: reinforcement.toFixed(4)
  });
}

return updates.map(u => ({ json: u }));

// Queue actions for thick paths
const items = $input.all();

const actions = items.map((item, idx) => {
  const data = item.json;

  return {
    action_type: 'allocate_attention',
    tendril_key: data.tendril_key,
    priority: Math.max(0, 100 - idx * 10),
    variant_id: data.current_variant_id || null,
    payload_json: {
      reason: 'Top nutrient path in last 7d',
      nutrient_7d: data.nutrient_7d,
      events_7d: data.events_7d,
      pheromone_weight: data.pheromone_weight,
      evolutionary_mode: data.evolutionary_mode
    }
  };
});

return actions.map(a => ({ json: a }));

// Emit summary
const rollup = $input.first().json;
const thickPaths = $input.all().slice(0, 3);

const summary = {
  run_timestamp: new Date().toISOString(),
  tendrils_reinforced: rollup.length || 0,
  variants_updated: rollup.filter(r => r.variant_id).length || 0,
  thick_paths_selected: thickPaths.length,
  top_tendril: thickPaths[0]?.tendril_key || 'none',
  top_nutrient_7d: thickPaths[0]?.nutrient_7d || 0
};

console.log('🧠 Organism brain cycle complete:', JSON.stringify(summary, null, 2));

return { json: summary };
